/**
 * Pre-compute hash-based bag-of-words embeddings for the entire corpus
 * and write them to src/generated/embeddings.ts at build time.
 *
 * The generated file is committed and baked into the binary so vector
 * search never needs to compute corpus embeddings at startup.
 *
 * Run: bun run scripts/generate-embeddings.ts
 *
 * Storage: Float64Array quantized to Int16 (saves 4×) via scale factor.
 * At runtime, decode: raw[i] = stored[i] / SCALE
 */

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { Command } from "commander";

const DIM = 2048;
const SCALE = 10000; // quantize floats to 4 decimal places → Int16

function embed(text: string): number[] {
  const tokens = text.toLowerCase().split(/[^a-z0-9]+/).filter((t) => t.length > 2);
  const vec = new Array(DIM).fill(0);
  for (const t of tokens) {
    let h = 0;
    for (let i = 0; i < t.length; i++) {
      h = ((h << 5) - h) + t.charCodeAt(i);
      h |= 0;
    }
    vec[((h % DIM) + DIM) % DIM]! += 1;
  }
  const norm = Math.sqrt(vec.reduce((s, v) => s + v * v, 0));
  if (norm > 0) for (let i = 0; i < DIM; i++) vec[i]! /= norm;
  return vec;
}

const { initPlugins } = await import("../src/registry");
const { buildCorpus } = await import("../src/plugins/docs/corpus");

const program = new Command("bee");
program.exitOverride();
await initPlugins(program);
const corpus = buildCorpus(program);

const ids: string[] = [];
const values: number[] = [];

for (const item of corpus) {
  const text = [item.title, item.description, item.body].filter(Boolean).join(" ");
  ids.push(item.id);
  values.push(...embed(text));
}

// Quantize to Int16: round(float * SCALE), clamp to [-32768, 32767]
const quantized = new Int16Array(values.length);
for (let i = 0; i < values.length; i++) {
  const v = Math.round(values[i]! * SCALE);
  quantized[i] = Math.max(-32768, Math.min(32767, v));
}

const base64 = Buffer.from(quantized.buffer).toString("base64");

const outPath = join(import.meta.dir, "..", "src", "generated", "embeddings.ts");
const code = [
  "// Auto-generated by scripts/generate-embeddings.ts — do not edit manually.",
  `// Generated: ${new Date().toISOString()}`,
  `// Corpus: ${ids.length} items × ${DIM} dim`,
  "",
  `export const DIM = ${DIM} as const;`,
  `export const SCALE = ${SCALE} as const;`,
  `export const VEC_IDS: readonly string[] = ${JSON.stringify(ids)};`,
  "",
  `// Quantized Int16 flat array (base64). Decode: Int16Array.fromBase64(VEC_B64)`,
  `export const VEC_B64 = "${base64}";`,
].join("\n");

writeFileSync(outPath, code, "utf-8");
console.log(`✓ ${ids.length}×${DIM} (${quantized.byteLength} bytes) → ${outPath}`);
